def module_basis(vectors,p=3,exponent=2):
 modulus=p**exponent;piv={}
 def valuation(v):
  r=0
  while v%p==0:r+=1;v//=p
  return r
 for a0 in vectors:
  queue=[a0]
  while queue:
   a=queue.pop().copy()
   while a:
    key=min(a);v=valuation(a[key])
    if key in piv:
     b=piv[key];w=valuation(b[key])
     if v>=w:
      a=add(a,b,-(a[key]//(p**w)),modulus);continue
     else:
      old=piv.pop(key);queue.append(old)
    inv=pow(a[key]//(p**v),-1,modulus)
    a={k:t*inv%modulus for k,t in a.items() if t*inv%modulus}
    piv[key]=a
    if v:
     extra={k:t*p**(exponent-v)%modulus for k,t in a.items() if t*p**(exponent-v)%modulus}
     if extra:queue.append(extra)
    break
 return list(piv.values())

# Algorithm checks against exhaustive finite spans in a small module.
from itertools import product
import random
for trial in range(20):
 vecs=[{(i,):random.randrange(9) for i in range(3)} for j in range(3)]
 vecs=[{k:v for k,v in a.items() if v} for a in vecs]
 bs=module_basis(vecs)
 def span(vs):
  out=set()
  for cs in product(range(9),repeat=len(vs)):
   out.add(tuple(sum(c*v.get((i,),0) for c,v in zip(cs,vs))%9 for i in range(3)))
  return out
 assert span(vecs)==span(bs),(vecs,bs)
print('module algorithm random exhaustive tests passed',flush=True)
p=9;gs=generators(3,p);bs=gs
for c in range(2,9):
 path=Path(f'workspace/agent3_IA3_mod9_degree{c}_basis.pkl')
 if path.exists():bs=pickle.loads(path.read_bytes());continue
 start=time.time();bs=module_basis((bracket(a,b,3,p) for a in gs for b in bs))
 print('mod9_IA3_image',c,len(bs),'unit',sum(min(b.values())>=0 and b[min(b)]%3!=0 for b in bs),'seconds',time.time()-start,flush=True)
 path.write_bytes(pickle.dumps(bs))
with open('workspace/agent4_candidate_tau8.pkl','rb') as f:a=pickle.load(f)
a={k:int(v)%9 for k,v in a.items() if int(v)%9};piv={min(b):b for b in bs};count=0
while a:
 k=min(a)
 if k not in piv:break
 b=piv[k];lead=b[k]
 if a[k]%lead:break
 a=add(a,b,-(a[k]//lead),9);count+=1
print('candidate mod9 reduced',count,'residual terms',len(a),'lead',min(a) if a else None,flush=True)
Path('workspace/agent3_candidate_tau8_mod9_residue.pkl').write_bytes(pickle.dumps(a))

