gs=[gs0[i] for i in [0,1,3,4,6,7,2,5,8]]
halls=[(j,i,k) for i in range(8) for j in range(i+1,9) for k in range(i,9)]
assert len(halls)==240
B={};oracle=load();hits=[]
def inv(w):return [-x for x in w[::-1]]
